let launches = 0;
const launchBtn = document.querySelector("#launch");

function onLaunch() {
  // add to launches, write to #info, remove the listener
  launches++;
  document.querySelector("#info").textContent = "Launch! Engines running.";
  launchBtn.removeEventListener("click", onLaunch);
}

launchBtn.addEventListener("click", onLaunch);

